// Input validation and preparation
const input = $input.first().json;

// Validate required fields
if (!input.topic || typeof input.topic !== 'string' || input.topic.trim().length === 0) {
  return {
    json: {
      success: false,
      error: 'Invalid input: topic is required and must be a non-empty string',
      agentType: 'deep_research',
      errorCode: 'INVALID_INPUT'
    }
  };
}

// Limit topic length for reasonable research scope
const sanitizedTopic = input.topic.trim().slice(0, 1000);

// Estimate research complexity
const wordCount = sanitizedTopic.split(/\s+/).length;
const complexity = wordCount > 50 ? 'high' : (wordCount > 20 ? 'medium' : 'low');

return {
  json: {
    topic: sanitizedTopic,
    sessionId: input.sessionId || $execution.id,
    startTime: Date.now(),
    complexity,
    metadata: {
      originalLength: input.topic.length,
      wordCount,
      complexity,
      executionId: $execution.id
    }
  }
};

// Format research output with comprehensive metadata
const input = $('Validate Input').first().json;
const result = $input.first().json;

const executionTime = Date.now() - (input.startTime || Date.now());

// Extract sources and topics explored
let sources = [];
let topicsExplored = [];
let thinkingOutput = null;

try {
  if (result.intermediateSteps) {
    for (const step of result.intermediateSteps) {
      // Capture thinking output
      if (step.action?.tool === 'think_step_by_step' && step.observation) {
        thinkingOutput = step.observation;
      }

      // Track topics from search queries
      if (step.action?.toolInput) {
        const input = step.action.toolInput;
        if (!topicsExplored.includes(input)) {
          topicsExplored.push(input);
        }
      }

      // Extract sources
      if (step.observation) {
        const obs = typeof step.observation === 'string'
          ? step.observation
          : JSON.stringify(step.observation);

        // Extract URLs
        const urlRegex = /https?:\/\/[^\s<>"'\]\)]+/g;
        const urls = obs.match(urlRegex) || [];
        for (const url of urls) {
          if (!sources.find(s => s.url === url)) {
            let type = 'web';
            if (url.includes('wikipedia')) type = 'wikipedia';
            else if (url.includes('.gov')) type = 'government';
            else if (url.includes('.edu')) type = 'academic';
            sources.push({ url, type });
          }
        }
      }
    }
  }
} catch (e) {
  // Non-critical parsing error
}

// Assess confidence based on source diversity
let confidenceLevel = 'low';
const sourceTypes = [...new Set(sources.map(s => s.type))];
if (sourceTypes.length >= 3 && sources.length >= 5) {
  confidenceLevel = 'high';
} else if (sourceTypes.length >= 2 && sources.length >= 3) {
  confidenceLevel = 'medium';
}

return {
  json: {
    success: true,
    agentType: 'deep_research',
    output: result.output || 'Research completed',
    sources,
    researchDepth: 'comprehensive',
    topicsExplored,
    confidenceLevel,
    thinkingOutput,
    metadata: {
      executionTime,
      toolCalls: (result.intermediateSteps || []).length,
      sourceCount: sources.length,
      topicCount: topicsExplored.length,
      complexity: input.complexity,
      executionId: input.metadata?.executionId
    }
  }
};

// Handle validation error
const input = $input.first().json;

return {
  json: {
    success: false,
    agentType: 'deep_research',
    error: input.error || 'Validation failed',
    errorCode: input.errorCode || 'VALIDATION_ERROR',
    output: null,
    sources: [],
    confidenceLevel: 'none',
    metadata: {
      executionId: $execution.id
    }
  }
};
